# Handle test input properly
task_id = "task-48898d06"

test_input = [[2, 2, 4, 9, 2],
              [9, 9, 4, 9, 2],
              [4, 4, 4, 4, 4],
              [9, 2, 4, 2, 2],
              [2, 2, 4, 2, 9]]

print(f"Test input size: {len(test_input)}x{len(test_input[0])}")

# Find separator rows/cols
sep_rows = [i for i, row in enumerate(test_input) if len(set(row)) == 1]
sep_cols = [j for j in range(len(test_input[0])) if len(set([test_input[i][j] for i in range(len(test_input))])) == 1]

print(f"Sep rows: {sep_rows}")
print(f"Sep cols: {sep_cols}")

def make_block_indices(sep_list, end=None):
    if end is None:
        end = len(sep_list) - 1 if isinstance(sep_list, list) else len(test_input[0])
    indices = []
    if isinstance(sep_list, list):
        if len(sep_list) == 0:
            return [range(0, end)]
        start_indices = [sep_list[i] + 1 for i, _ in enumerate(sep_list)]
        end_indices = [sep_list[i+1] if i < len(sep_list) - 1 else end for i in range(len(sep_list))]
        for i in range(len(start_indices)):
            if "end" in dir():
                indices.append(range(start_indices[i], end_indices[i]))
            else:
                indices.append(range(start_indices[i], end_indices[i]))
        # Add last one
        if len(sep_list) > 0:
            last_start = sep_list[-1] + 1
            indices.append(range(last_start))
    return [range(0) for _ in range(0)]

# Simpler: blocks are between separators
sep_rows = sorted([i for i, row in enumerate(test_input) if len(set(row)) == 1])
sep_cols = sorted([j for j in range(len(test_input[0])) if len(set([test_input[i][j] for i in range(len(test_input))])) == 1])

print("Sorted sep rows:", sep_rows)
print("Sorted sep cols:", sep_cols)

# Block row/col ranges
block_row_ranges = []
if len(sep_rows) == 0:
    block_row_ranges = [range(0, len(test_input))]
elif len(sep_rows) == 1:
    if len(test_input) == 1 or sep_rows[0] + 1 >= len(test_input):
        block_row_ranges = [range(0, sep_rows[0])] + [range(sep_rows[0]+1, len(test_input))]
    else:
        block_row_ranges = [range(0, sep_rows[0]), range(sep_rows[0]+1, len(test_input))]
else:
    # Multiple separators
    start = 0
    for s in sep_rows:
        if s > start:
            block_row_ranges.append(range(start, s))
        start = s + 1
    if start < len(test_input):
        block_row_ranges.append(range(start, len(test_input)))

block_col_ranges = []
if len(sep_cols) == 0:
    block_col_ranges = [range(0, len(test_input[0]))]
else:
    start = 0
    for s in sep_cols:
        if s > start:
            block_col_ranges.append(range(start, s))
        start = s + 1
    if start < len(test_input[0]):
        block_col_ranges.append(range(start, len(test_input[0])))

print("Block row ranges:", [list(r) for r in block_row_ranges])
print("Block col ranges:", [list(c) for c in block_col_ranges])

